import com.crowdin.client.core.http.exceptions.CrowdinApiException;
import com.crowdin.client.core.http.exceptions.HttpException;
import com.crowdin.client.core.http.impl.json.JacksonJsonTransformer;
import com.crowdin.client.projectsgroups.model.Project;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.ExpectedException;

public class JacksonJsonTransformerTest {

	@Rule
    public ExpectedException expectedException = ExpectedException.none();

	@Test
	public void parseNonEmptyJsonTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
		String json = "{\"id\":1, \"name\":\"project1\"}";
		Project project = transformer.parse(json, Project.class);
		Assert.assertNotNull(project);
		Assert.assertEquals(1, project.getId());
		Assert.assertEquals("project1", project.getName());
	}

	@Test
	public void parseEmptyJsonTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
		String json = "{}";
		Project project = transformer.parse(json, Project.class);
		Assert.assertNotNull(project);
	}

	@Test
	public void parseNullJsonTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
		expectedException.expect(NullPointerException.class);
		transformer.parse(null, Project.class);
	}

	@Test
	public void parseInvalidJsonTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
		String json = "Invalid JSON String";
		expectedException.expect(CrowdinApiException.class);
		transformer.parse(json, Project.class);
	}

	@Test
	public void convertNonNullObjectTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
		Project project = new Project();
		project.setId(1);
		project.setName("project1");
		String json = transformer.convert(project);
		Assert.assertEquals("{\"id\":1,\"name\":\"project1\"}", json);
	}

	@Test
	public void convertNullObjectTest() {
		JacksonJsonTransformer transformer = new JacksonJsonTransformer();
		expectedException.expect(NullPointerException.class);
		transformer.convert(null);
	}
}
